static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

#define TIL_I 32
#define TIL_J 32

#pragma omp parallel default(none) shared(ex, ey, hz, _fict_) private(t)
  {
    for (t = 0; t < _PB_TMAX; t++)
      {
        /* Fused ey boundary condition and ey update, tiled. */
#pragma omp for collapse(2) schedule(static)
        for (int ii = 0; ii < _PB_NX; ii += TIL_I)
          for (int jj = 0; jj < _PB_NY; jj += TIL_J)
            {
              int iend = ii + TIL_I < _PB_NX ? ii + TIL_I : _PB_NX;
              int jend = jj + TIL_J < _PB_NY ? jj + TIL_J : _PB_NY;
              for (i = ii; i < iend; i++)
#pragma omp simd
                for (j = jj; j < jend; j++)
                  {
                    if (i == 0)
                      ey[i][j] = _fict_[t];
                    else
                      ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
                    if (j > 0)
                      ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
                  }
            }

        /* hz update, tiled. Implicit barrier ensures ey/ex are ready. */
#pragma omp for collapse(2) schedule(static)
        for (int ii = 0; ii < _PB_NX - 1; ii += TIL_I)
          for (int jj = 0; jj < _PB_NY - 1; jj += TIL_J)
            {
              int iend = ii + TIL_I < _PB_NX - 1 ? ii + TIL_I : _PB_NX - 1;
              int jend = jj + TIL_J < _PB_NY - 1 ? jj + TIL_J : _PB_NY - 1;
              for (i = ii; i < iend; i++)
#pragma omp simd
                for (j = jj; j < jend; j++)
                  hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*(ex[i][j+1] - ex[i][j] +
                                       ey[i+1][j] - ey[i][j]);
            }
      }
  }

#pragma endscop
}

